import React from 'react';
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer
} from 'recharts';
import type { WidgetProps } from '../types';
import { WidgetDataGuard } from '../components/WidgetDataGuard';
import { resolveLabel } from '../utils/resolveChartFields';
import { useChartData } from '../hooks/useChartData';
import { LINE_CHART_COLORS } from '../utils/chartColors';

const ChartLine: React.FC<WidgetProps> = ({ definition, period, preference }) => {
  const { chartData, valueKeys, categoryField, aliases, data, loading, error } =
    useChartData(definition, preference, period);

  return (
    <WidgetDataGuard loading={loading} error={error} data={data}>
    <div className="w-full h-full p-4">
      <ResponsiveContainer width="100%" height="100%">
        <LineChart data={chartData} margin={{ top: 10, right: 20, left: -20, bottom: 0 }}>
          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#E2E8F0" />
          <XAxis dataKey={categoryField} axisLine={false} tickLine={false} tick={{ fill: '#718096', fontSize: 12 }} dy={10} />
          <YAxis axisLine={false} tickLine={false} tick={{ fill: '#718096', fontSize: 12 }} tickFormatter={(value) => value.toLocaleString('es-CO')} />
          <Tooltip cursor={{ stroke: '#E2E8F0', strokeWidth: 2 }} contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)' }} />
          {valueKeys.length > 1 && <Legend wrapperStyle={{ paddingTop: '10px' }} />}
          {valueKeys.map((key, i) => (
            <Line key={key} type="monotone" dataKey={key} name={resolveLabel(key, aliases)} stroke={LINE_CHART_COLORS[i % LINE_CHART_COLORS.length]} strokeWidth={3}
              dot={{ r: 4, fill: LINE_CHART_COLORS[i % LINE_CHART_COLORS.length], strokeWidth: 2, stroke: '#FFF' }} activeDot={{ r: 6 }} />
          ))}
        </LineChart>
      </ResponsiveContainer>
    </div>
    </WidgetDataGuard>
  );
};

export default ChartLine;
